// Full encyclopedia entries: Chile, valle-central. Built from the Vitis Mundi atlas plus researched rules and history; checked 14 November 2026.
(function(){
APXF["cl-alhue"] = {"lede": "Area matching Alhué commune, a secluded valley in the coastal range at the south-western edge of the Metropolitan Region, with a few vineyards among old haciendas.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Alhué is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Area within Valle del Maipo (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-apalta"] = {"lede": "Apalta is the most famous hillside in Chile: a horseshoe of granite slopes opening south onto the Tinguiririca river near Santa Cruz in Colchagua, recognised as its own DO in 2018 with about 1,007 ha of vineyards.", "facts": [["Category", "DO"], ["Recognized", "2018"], ["Vineyard area", "About 1,007 ha"], ["Main grapes", "Carmenère, Cabernet Sauvignon, Syrah, Merlot, Malbec, Grenache, Mourvèdre, Carignan"]], "sections": [["The place", "<p>The hills shelter it on three sides, so morning mist lingers and direct sun arrives late and leaves early, slowing ripening in what would otherwise be a hot valley. Valley floor clay suits Cabernet and Carmenère; the poorer granitic slopes, terraced since the 1990s, increasingly carry Syrah, Grenache, Mourvèdre and Carignan.</p><p>The names are legendary: Lapostolle's Clos Apalta, a Carmenère-led blend from vines planted in the early 20th century, made in a gravity winery dug into the hill; Montes Alpha M and the steep Syrah of Montes Folly; and Neyen, an old adobe estate with Carmenère and Cabernet over a century old. Apalta wines are dense and dark but carry a fresh, granite-edged finish. Labels may add the complement *Entre Cordilleras*.</p><p>Decomposed granite on steep slopes, deeper alluvial clay on the horseshoe floor; south-facing amphitheatre with shortened direct sun hours and morning mist.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["History", "<p>Apalta is a horseshoe of granite hillsides north of the Tinguiririca river. Montes planted its Folly Syrah on slopes once thought unplantable, and Lapostolle's Clos Apalta, a Carmenère-led blend, became one of Chile's most famous wines. Apalta became its own DO area in 2018.</p>"], ["In the glass", "<p>Rich, ripe Carmenère, Syrah, Cabernet and blends with fine, sun-polished tannin.</p>"], ["For the exam", "<p>DO 2018; Montes Alpha M and Folly; Clos Apalta.</p>"]], "producers": ["Lapostolle (Clos Apalta)", "Montes (Alpha M, Folly, Purple Angel)", "Neyen", "Santa Rita", "Ventisquero (Pangea)", "Las Niñas"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-buin"] = {"lede": "Area defined by Buin, Paine and San Bernardo communes, the Central Maipo heartland south of Santiago.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>It includes Alto Jahuel, home of Santa Rita (founded 1880), and Viña Carmen, where in 1994 Jean-Michel Boursiquot identified Carmenère among the vines Chileans called Merlot. Warm days and alluvial soils give rich Cabernet and Carmenère. Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Buin is classed as 'Andes', so its wines may add that term.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Area within Valle del Maipo (Valle Central region); 'Andes' area.</p>"]], "producers": ["Santa Rita", "Viña Carmen", "Antiyal", "Cousiño Macul (Buin)"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-calera-de-tango"] = {"lede": "Area matching Calera de Tango commune, a small farming district south-west of Santiago with some Cabernet and other reds.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Calera de Tango is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Area within Valle del Maipo (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-cauquenes"] = {"lede": "Cauquenes is the epicentre of Chile's rediscovered heritage.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"], ["Main grapes", "País, Carignan, Cinsault, Malbec"]], "sections": [["The place", "<p>On the granite hills of the coastal range, bush-trained, dry-farmed País and Carignan up to 100 to 200 years old grow without irrigation, ploughed by horse, picked into wooden boxes. For decades the grapes went to cheap *pipeño* and jug wine; since the late 2000s VIGNO Carignan, Miguel Torres's sparkling País (Estelado) and a crowd of small natural-leaning producers have turned the commune into a source of juicy, earthy, low-alcohol reds. It is the single area of the Valle del Tutuvén zone and part of the Secano Interior. Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Cauquenes is classed as 'Entre Cordilleras', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["History", "<p>Cauquenes is the centre of Maule's old-vine revival. VIGNO producers and small growers such as those around the Cooperativa Agrícola Vitivinícola de Cauquenes make Carignan and País from dry-farmed vines on granite.</p>"], ["In the glass", "<p>Juicy, high-acid Carignan; rustic, fragrant País.</p>"], ["For the exam", "<p>Tutuvén zone; Carignan, País; VIGNO; Secano Interior eligible.</p>"]], "producers": ["Undurraga (T.H. VIGNO)", "Garage Wine Co", "Viña Lomas de Cauquenes cooperative", "Miguel Torres"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-chimbarongo"] = {"lede": "Area matching Chimbarongo commune in east Colchagua, known for wicker crafts as well as vineyards on the Andean side of the valley.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Chimbarongo is classed as 'Andes', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Andes' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-colbun"] = {"lede": "Area matching Colbún commune on the Andean side of Maule, near the Colbún reservoir; piedmont vineyards give fresher reds.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Colbún is classed as 'Andes', so its wines may add that term.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Andes' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-colina"] = {"lede": "Area matching Colina commune north of Santiago, Chacabuco province.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Vineyards are few and squeezed by suburban growth. Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Colina is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Area within Valle del Maipo (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-coltauco"] = {"lede": "Area matching Coltauco commune in west Cachapoal, a mixed farming district with some red plantings.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Coltauco is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Ripe Carmenère (especially from Peumo), Cabernet and Bordeaux blends.</p>"], ["For the exam", "<p>Area within Valle del Cachapoal (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-curepto"] = {"lede": "Area matching Curepto commune near the Mataquito mouth, in the coastal secano, with old dry-farmed País and newer coastal plantings.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Costa*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Curepto is classed as 'Costa', so its wines may add that term.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Costa' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-empedrado"] = {"lede": "Area matching Empedrado commune in Maule's coastal range, one of the few slate terroirs in Chile.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Miguel Torres planted a vineyard on its schist slopes in the 2000s, producing a rare, mineral Pinot Noir. Labels may add the complement *Costa*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Empedrado is classed as 'Costa', so its wines may add that term.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Costa' area.</p>"]], "producers": ["Miguel Torres"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-isla-de-maipo"] = {"lede": "Area matching Isla de Maipo commune, an island-like tract between arms of the Maipo river in central Maipo.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>De Martino and Tarapacá are based here; the warm, alluvial valley floor produces ripe Cabernet, Carmenère and Syrah. Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Isla de Maipo is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Area within Valle del Maipo (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": ["De Martino", "Viña Tarapacá"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-la-estrella"] = {"lede": "Area matching La Estrella commune in the western hills of Colchagua, with granitic soils and limited, recent plantings.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. La Estrella is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-lampa"] = {"lede": "Area matching Lampa commune north-west of Santiago; minor vineyard area in a rapidly urbanising basin.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Lampa is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Area within Valle del Maipo (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-licanten"] = {"lede": "Licantén is a small coastal DO of about 124 ha in the Mataquito valley of Curicó, created in 2018.", "facts": [["Category", "DO"], ["Recognized", "2018"], ["Vineyard area", "About 124 ha"], ["Main grapes", "Malbec, Cabernet Sauvignon, Cabernet Franc, Merlot, Carmenère"]], "sections": [["The place", "<p>Its only producer, La Ronciere, planted the Idahue vineyard in 2012 about 24 km from the sea, entirely to red varieties, on four soil types including llicorella-like slate, lutites, gravel and clay. Cool Pacific air gives Malbec, Cabernet Sauvignon, Cabernet Franc, Merlot and Carmenère a fresher, more tensile profile than the inland Curicó style. Labels may add the complement *Costa*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["In the glass", "<p>Fresh Sauvignon Blanc, Cabernet and everyday blends.</p>"], ["For the exam", "<p>Coastal area of Curicó, about 124 ha; created 2018.</p>"]], "producers": ["La Ronciere"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-linares"] = {"lede": "Area defined by Linares and Yerbas Buenas communes, a large valley-floor vineyard zone with some old vines in the surrounding hills.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Linares is classed as 'Entre Cordilleras', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Entre Cordilleras' area; Secano Interior eligible.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-litueche"] = {"lede": "Area matching Litueche commune in Cardenal Caro province near the coast, a cool frontier with a handful of vineyards.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Costa*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Litueche is classed as 'Costa', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Costa' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-lolol"] = {"lede": "Area matching Lolol commune in west Colchagua, a valley of old adobe houses and newer hillside vineyards where coastal influence cools Syrah, Cabernet and Rhône varieties.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Costa*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Lolol is classed as 'Costa', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Costa' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-longavi"] = {"lede": "Area matching Longaví commune in southern Maule.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>The brand Longaví, from the Garcés Silva family's young winemakers, takes its name from the volcano. Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Longaví is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-los-lingues"] = {"lede": "Los Lingues is a 492 ha Andes-side DO in San Fernando commune, east Colchagua, created by Supreme Decree 56 of 2017 and published in 2018.", "facts": [["Category", "DO"], ["Recognized", "2018 (Decreto 56 of 2017)"], ["Vineyard area", "About 492 ha"], ["Main grapes", "Cabernet Sauvignon, Carmenère, Syrah, Cabernet Franc, Petit Verdot"]], "sections": [["The place", "<p>It takes its name from the colonial Hacienda Los Lingues, one of the oldest estates in Chile, and its vineyards (Koyle, Casa Silva, Siegel) sit on volcanic and colluvial soils with basalt rocks at the foot of the cordillera, where cool mountain breezes give firmer, fresher Cabernet, Carmenère and Syrah than the warm valley floor. In June 2026 Chile's Supreme Court upheld the DO against a trademark holder who had registered 'Los Lingues' brands since 1983, confirming that a denomination of origin can coexist with an earlier trademark. Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Andes-side area of Colchagua, 492 ha; created by Decree 56 of 2017.</p>"]], "producers": ["Koyle", "Casa Silva", "Siegel"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-machali"] = {"lede": "Area matching Machalí commune, a large Andean commune east of Rancagua reaching into the high cordillera; its vineyards sit on the piedmont near the Cachapoal canyon.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Machalí is classed as 'Andes', so its wines may add that term.</p>"], ["In the glass", "<p>Ripe Carmenère (especially from Peumo), Cabernet and Bordeaux blends.</p>"], ["For the exam", "<p>Area within Valle del Cachapoal (Valle Central region); 'Andes' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-marchigue"] = {"lede": "Area matching Marchigüe commune, the west Colchagua frontier planted from the late 1990s, notably by Montes and Montgras.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Rolling granite hills, a breeze from the Pacific and low rainfall give Syrah, Cabernet and Carmenère with freshness and grip. Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Marchigüe is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": ["Montes", "Montgras"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-maria-pinto"] = {"lede": "Area matching María Pinto commune, in the hills west of Santiago between Curacaví and Melipilla, a minor source of red grapes.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. María Pinto is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Area within Valle del Maipo (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-melipilla"] = {"lede": "Area defined by Melipilla and San Pedro communes, the western 'Pacific Maipo' sector, where sea breezes reach through the coastal range.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Newer plantings of Cabernet, Syrah and some whites experiment with this cooler fringe. Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Melipilla is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Area within Valle del Maipo (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-molina"] = {"lede": "Area defined by Molina, Río Claro and Curicó communes.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>It holds San Pedro's vast estate at Lontué and Miguel Torres's winery near Curicó, where Torres began modernising Chilean winemaking in 1979. Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Molina is classed as 'Andes', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["History", "<p>Molina holds Viña San Pedro's huge estate, often called one of the largest single vineyards in South America.</p>"], ["In the glass", "<p>Fresh Sauvignon Blanc, Cabernet and everyday blends.</p>"], ["For the exam", "<p>Lontué zone; San Pedro; 'Andes' area; Secano Interior eligible.</p>"]], "producers": ["San Pedro", "Miguel Torres"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-nancagua"] = {"lede": "Area defined by Nancagua and Placilla communes on the Colchagua valley floor, warm alluvial land with large vineyards of Cabernet, Carmenère and Merlot.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Nancagua is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-palmilla"] = {"lede": "Area matching Palmilla commune in central Colchagua, which includes the colonial Hacienda El Huique; Montgras and others farm warm valley vineyards nearby.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Palmilla is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-paredones"] = {"lede": "Area matching Paredones commune, Colchagua's coastal end about 10 to 15 km from the Pacific.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Casa Silva and others planted here in the 2000s and showed that the warm-red zone of Colchagua can also make saline Sauvignon Blanc and taut Pinot Noir on granite and schist. Labels may add the complement *Costa*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Paredones is classed as 'Costa', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Costa' area.</p>"]], "producers": ["Casa Silva"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-parral"] = {"lede": "Area matching Parral commune, birthplace of Pablo Neruda, in southern Maule; mixed irrigated and dry-farmed vineyards.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Parral is classed as 'Entre Cordilleras', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Entre Cordilleras' area; Secano Interior eligible.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-pencahue"] = {"lede": "Area matching Pencahue commune west of Talca, warm and relatively dry, known for ripe reds and dry-farmed old vines.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Pencahue is classed as 'Entre Cordilleras', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Entre Cordilleras' area; Secano Interior eligible.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-peralillo"] = {"lede": "Area matching Peralillo commune, home of Los Vascos, the estate bought in 1988 by Domaines Barons de Rothschild (Lafite), one of the first foreign investments of Chile's modern wine boom.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Peralillo is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": ["Los Vascos"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-peumo"] = {"lede": "Area defined by Peumo, Pichidegua, Las Cabras and San Vicente communes in west Cachapoal: Chile's Carmenère grand cru in all but name.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Clay-rich alluvial soils near the Cachapoal river, a warm sheltered bowl and a long autumn let the late-ripening grape lose its green pyrazines. Concha y Toro's Carmín de Peumo and Terrunyo Carmenère come from its Peumo vineyard; Vik sits in the Millahue valley of San Vicente. Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Peumo is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["History", "<p>Peumo's warm, clay-rich valley floor near the Cachapoal river ripens Carmenère fully, which matters because the variety turns green and pyrazine-heavy if picked early. Concha y Toro's Carmín de Peumo is the reference.</p>"], ["In the glass", "<p>Ripe, plush Carmenère with red pepper and spice.</p>"], ["For the exam", "<p>Cachapoal; Carmenère; Carmín de Peumo.</p>"]], "producers": ["Concha y Toro (Carmín de Peumo)", "Vik"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-pirque"] = {"lede": "Area matching Pirque commune, on the south bank of the Maipo where the river leaves the Andes.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Concha y Toro founded its winery here in 1883 at the Subercaseaux family's country house, and the commune also holds Haras de Pirque (a horse-stud estate turned winery) and William Fèvre Chile. Cold air pouring out of the Maipo canyon at night keeps Cabernet fresh and structured. Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Pirque is classed as 'Andes', so its wines may add that term.</p>"], ["History", "<p>Pirque is where Melchor Concha y Toro founded his estate in 1883; its old house and cellar, the Casillero del Diablo, gave the company its best-known legend: the founder spread the story that the devil lived in his cellar to keep thieves away.</p>"], ["In the glass", "<p>Cabernet Sauvignon with freshness and mint.</p>"], ["For the exam", "<p>Andes area; Concha y Toro 1883; Casillero del Diablo legend.</p>"]], "producers": ["Concha y Toro", "Haras de Pirque", "William Fèvre Chile"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-puente-alto"] = {"lede": "Area matching Puente Alto and La Pintana communes on the north bank of the Maipo: the most valuable Cabernet terroir in Chile.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>On a stony alluvial terrace at about 650 m sit Concha y Toro's Don Melchor vineyard, Almaviva and Viñedo Chadwick, side by side. Deep, free-draining river cobbles, cool mountain nights and a long dry season give Cabernet of fine tannin, cassis and graphite that ages for decades. Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Puente Alto is classed as 'Andes', so its wines may add that term.</p>"], ["History", "<p>Puente Alto's alluvial terrace on the north bank of the Maipo holds Concha y Toro's Don Melchor vineyard, Almaviva, and Viñedo Chadwick, planted by Eduardo Chadwick in 1992 on his father's polo field; in the 2004 Berlin Tasting its 2000 vintage ranked first against top Bordeaux and Super Tuscans.</p>"], ["In the glass", "<p>Fine, cassis-and-graphite Cabernet Sauvignon.</p>"], ["For the exam", "<p>Andes area of Maipo; Don Melchor, Almaviva, Viñedo Chadwick; Berlin Tasting 2004.</p>"]], "producers": ["Don Melchor", "Almaviva", "Viñedo Chadwick"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-pumanque"] = {"lede": "Area matching Pumanque commune in the west of Colchagua, a rural district of old haciendas with small coastal-influenced plantings.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Costa*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Pumanque is classed as 'Costa', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Costa' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-rancagua"] = {"lede": "Area defined by Rancagua, Graneros, Mostazal, Codegua and Olivar communes around the O'Higgins capital, the northern gateway of Cachapoal, with mixed red plantings.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Rancagua is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Ripe Carmenère (especially from Peumo), Cabernet and Bordeaux blends.</p>"], ["For the exam", "<p>Area within Valle del Cachapoal (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-rauco"] = {"lede": "Area defined by Rauco and Hualañé communes, west of Curicó city, with dry-farmed hills that qualify for the Secano Interior special DO for País and Cinsault.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Rauco is classed as 'Entre Cordilleras', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["In the glass", "<p>Fresh Sauvignon Blanc, Cabernet and everyday blends.</p>"], ["For the exam", "<p>Area within Valle de Curicó (Valle Central region); 'Entre Cordilleras' area; Secano Interior eligible.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-rengo"] = {"lede": "Area defined by Rengo, Malloa and Quinta de Tilcoco communes in central Cachapoal, with Torreón de Paredes and Misiones de Rengo among its wineries.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Rengo is classed as 'Andes', so its wines may add that term.</p>"], ["In the glass", "<p>Ripe Carmenère (especially from Peumo), Cabernet and Bordeaux blends.</p>"], ["For the exam", "<p>Area within Valle del Cachapoal (Valle Central region); 'Andes' area.</p>"]], "producers": ["Torreón de Paredes", "Misiones de Rengo"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-requinoa"] = {"lede": "Area matching Requínoa commune at the foot of the Andes in east Cachapoal.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Altaïr, the San Pedro project created with Château Dassault in the early 2000s, and other Andes-side estates grow structured Cabernet blends on stony colluvial slopes. Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Requínoa is classed as 'Andes', so its wines may add that term.</p>"], ["In the glass", "<p>Ripe Carmenère (especially from Peumo), Cabernet and Bordeaux blends.</p>"], ["For the exam", "<p>Area within Valle del Cachapoal (Valle Central region); 'Andes' area.</p>"]], "producers": ["Altaïr"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-retiro"] = {"lede": "Area matching Retiro commune in southern Maule, irrigated farmland with vineyards for Cabernet and País.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Retiro is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-romeral"] = {"lede": "Area defined by Romeral and Teno communes, the Andes side of Curicó, where cool mountain breezes favour Sauvignon Blanc and Cabernet.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Romeral is classed as 'Andes', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["In the glass", "<p>Fresh Sauvignon Blanc, Cabernet and everyday blends.</p>"], ["For the exam", "<p>Area within Valle de Curicó (Valle Central region); 'Andes' area; Secano Interior eligible.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-sagrada-familia"] = {"lede": "Area matching Sagrada Familia commune, south-west of Curicó, where valley floor gives way to dry-farmed hills with old País; part of the Secano Interior.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Sagrada Familia is classed as 'Entre Cordilleras', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["In the glass", "<p>Fresh Sauvignon Blanc, Cabernet and everyday blends.</p>"], ["For the exam", "<p>Area within Valle de Curicó (Valle Central region); 'Entre Cordilleras' area; Secano Interior eligible.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-san-clemente"] = {"lede": "Area matching San Clemente commune, a huge Andean commune east of Talca stretching to the Argentine border; vineyards on the piedmont give fresh Cabernet and Sauvignon Blanc.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. San Clemente is classed as 'Andes', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Andes' area; Secano Interior eligible.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-san-fernando"] = {"lede": "Area matching San Fernando commune, the eastern, Andes-side gateway to Colchagua.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>It contains the historic Hacienda Los Lingues (now its own DO), Casa Silva's Angostura winery and cool piedmont vineyards whose volcanic soils give firmer, fresher reds. Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. San Fernando is classed as 'Andes', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Andes' area.</p>"]], "producers": ["Casa Silva"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-san-javier"] = {"lede": "Area matching San Javier commune, the hub of Maule's old-vine revival.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Gillmore at Villavicencio and the Bouchon family at Mingre farm dry-farmed Carignan, País and Cabernet in the coastal hills, and many VIGNO Carignans come from here. Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. San Javier is classed as 'Entre Cordilleras', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Entre Cordilleras' area; Secano Interior eligible.</p>"]], "producers": ["Gillmore", "J. Bouchon"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-san-rafael"] = {"lede": "Area matching San Rafael commune north of Talca (not to be confused with Argentina's San Rafael DOC), a farming district with red plantings.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. San Rafael is classed as 'Entre Cordilleras', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Entre Cordilleras' area; Secano Interior eligible.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-santa-cruz"] = {"lede": "Area defined by Santa Cruz and Chépica communes, the tourist heart of Colchagua.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>It includes the Apalta horseshoe (now its own DO) and the town's Colchagua Museum; valley-floor vineyards here give generous Carmenère and Cabernet. Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Santa Cruz is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Area within Valle de Colchagua (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": ["Montes", "Lapostolle", "Viu Manent"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-santiago"] = {"lede": "Area defined in the decree by the communes of Peñalolén and La Florida, on Santiago's eastern edge.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>It holds the last city-fringe vineyards of the 19th-century estates: Cousiño Macul's original Macul vineyard (founded 1856, now much reduced by housing) and Viña Aquitania, founded in 1990 by Bruno Prats and Paul Pontallier of Bordeaux. Alluvial gravels under the Andes give firm, classic Cabernet. Labels may add the complement *Andes*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Santiago is classed as 'Andes', so its wines may add that term.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Area within Valle del Maipo (Valle Central region); 'Andes' area.</p>"]], "producers": ["Cousiño Macul", "Viña Aquitania"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-secano-interior"] = {"lede": "Secano Interior ('dry interior') is a special denomination of origin for wines made only from País and Cinsault grown on unirrigated land in the coastal hills and interior of Maule, Ñuble and Biobío.", "facts": [["Category", "DO"], ["Recognized", "amendment of Decree 464 (art. 3 bis); extended 2026"], ["Main grapes", "País (Mission, Criolla), Cinsault"]], "sections": [["The place", "<p>It rescues a category the 1994 law had effectively excluded: País was not even on the list of varieties allowed for DO wine. The decree names the qualifying areas (Rauco, Romeral, Molina, Sagrada Familia, Talca, Pencahue, San Clemente, San Rafael, San Javier, Villa Alegre, Parral, Linares, Cauquenes, Chillán, Quillón, Portezuelo, Coelemu and Yumbel) plus further communes; in July 2026 Decree 4 added Hualqui, Nacimiento, Los Ángeles, Laja, San Rosendo, Santa Juana and Tomé in Biobío.</p><p>The label can read 'Secano Interior' followed by the subregion, zone or area. SAG recorded 5.4 million litres under this DO in 2026, small but symbolic: it gives legal standing to the dry-farmed, own-rooted, often centenarian bush vines that are now Chile's hottest wine story.</p>"], ["The rules", "<p>A special denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Secano Interior is the exception: it is reserved for País or Cinsault from dry-farmed (unirrigated) vineyards in listed areas of Curicó, Maule, Itata and Bío-Bío, and the list of eligible communes has been extended several times, most recently in 2026.</p>"], ["History", "<p>The secano interior, the dry hills of the coastal range, was long dismissed as producing only cheap País. The special denomination, added to Decree 464, recognised the heritage of dry-farmed bush vines and gave the old varieties a legal identity.</p>"], ["In the glass", "<p>Light, fresh, earthy País and juicy, floral Cinsault.</p>"], ["For the exam", "<p>País or Cinsault only; dry-farmed; Maule, Itata, Bío-Bío; extended 2026.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-talagante"] = {"lede": "Area defined by Talagante, Peñaflor, El Monte and Padre Hurtado communes, west of Santiago.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Undurraga, founded here in 1885 by Francisco Undurraga, still has its historic winery and park at Santa Ana. Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Talagante is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Area within Valle del Maipo (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": ["Undurraga"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-talca"] = {"lede": "Area defined by Talca, Maule and Pelarco communes around Maule's capital, with irrigated valley vineyards and dry-farmed hills that qualify for Secano Interior.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Talca is classed as 'Entre Cordilleras', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Entre Cordilleras' area; Secano Interior eligible.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-til-til"] = {"lede": "Area matching Til Til commune in the far north of the Metropolitan Region, a dry, warm basin with scattered vineyards.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Til Til is classed as 'Entre Cordilleras', so its wines may add that term.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Area within Valle del Maipo (Valle Central region); 'Entre Cordilleras' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-central"] = {"lede": "The Central Valley region is the engine of Chilean wine: the long tectonic trough between the Andes and the coastal range from Santiago's Chacabuco province south to Cauquenes and Linares in Maule.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"], ["Vineyard area", "About 93,489 ha"], ["Main grapes", "Cabernet Sauvignon, Carmenère, Merlot, Syrah, Sauvignon Blanc, Chardonnay, País, Carignan"]], "sections": [["The place", "<p>It holds four subregions (Maipo, Rapel, Curicó, Maule) and, by SAG's figures, made 661.6 million litres of DO wine in 2026, 83.7% of the national total. The name covers everything from Puente Alto's Cabernet terraces to 19th-century País vines on the Maule dry-farmed hills, so on a serious bottle you will almost always see a subregion, zone or area instead.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["History", "<p>Spanish missionaries and settlers brought the País grape from Peru in the 1540s and 1550s. In 1851 Silvestre Ochagavía brought French vines and winemakers to his Santiago estate, and other mining and banking families followed, building estates such as Cousiño Macul (1856), Santa Rita (1880), Concha y Toro (1883) and Undurraga (1885). Phylloxera never reached Chile, protected by the Andes, the Atacama Desert, the Pacific and Patagonian ice, so its vines grow on their own roots. The Central Valley, the trough between the Andes and the Coastal Range, became the engine of the modern export boom from the late 1980s.</p>"], ["In the glass", "<p>Cabernet Sauvignon, Carmenère, Merlot and Sauvignon Blanc at every price level.</p>"], ["For the exam", "<p>Region: Maipo, Rapel (Cachapoal, Colchagua), Curicó, Maule; Ochagavía 1851; phylloxera-free.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-de-colchagua"] = {"lede": "Colchagua is Chile's red-wine showcase, the southern zone of Rapel running from the Andes past San Fernando and Santa Cruz to the Pacific at Pichilemu along the Tinguiririca river.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"], ["Main grapes", "Carmenère, Cabernet Sauvignon, Syrah, Malbec, Merlot, Cabernet Franc, Carignan; Sauvignon Blanc near the coast"]], "sections": [["The place", "<p>Its colonial haciendas (Los Lingues, Huique) grew País and wheat for centuries; the transformation began in the 1990s, when Aurelio Montes, Alexandra Marnier-Lapostolle and others bet on the granite hillsides of Apalta, and Robert Parker's praise for Montes Alpha M and Clos Apalta made the valley a brand. Santa Cruz grew into Chile's wine-tourism capital, with its Colchagua Museum and wine train.</p><p>The zone splits three ways. The eastern Andes side (San Fernando, Chimbarongo, Los Lingues) is cooler, with volcanic and colluvial soils. The centre (Nancagua, Santa Cruz, Palmilla, Peralillo and the Apalta horseshoe) is warm and sunny, the classic home of rich Carmenère, Cabernet, Syrah and Malbec. The west (Marchigüe, Lolol, Pumanque, Paredones, La Estrella, Litueche) is the 2000s frontier, where coastal breezes and granite give fresher Syrah, Cabernet and even Sauvignon Blanc at Paredones, 10 km from the sea.</p><p>Colchagua's house style is generous: ripe black fruit, soft tannins, sweet spice. The best hillside wines balance that sunshine with granite-born freshness.</p><p>Clay-loam and alluvium on the valley floor, decomposed granite on the hillsides (Apalta, Marchigüe), volcanic soils towards the Andes; Mediterranean climate with about 600 mm of rain, warm days and cooler coastal west.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["History", "<p>Colchagua's colonial haciendas grew wheat and cattle until the 1980s. Los Vascos was bought by Domaines Barons de Rothschild (Lafite) in 1988, Aurelio Montes planted the steep Apalta slopes, Lapostolle created Clos Apalta, and Colchagua became Chile's red-wine showcase. Santa Cruz's Museo de Colchagua and wine route made it Chile's best-known wine tourism region.</p>"], ["In the glass", "<p>Rich, ripe Cabernet, Carmenère, Syrah and blends; fresher whites and Pinot Noir from the coast.</p>"], ["For the exam", "<p>Rapel zone; Apalta; Los Vascos (Lafite, 1988); Montes, Lapostolle; Santa Cruz.</p>"]], "producers": ["Montes", "Lapostolle", "Neyen", "Casa Silva", "Montgras", "Los Vascos", "Viu Manent", "Ventisquero", "Koyle", "Errázuriz Ovalle", "Bisquertt"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-de-curico"] = {"lede": "Curicó, about 200 km south of Santiago, is where Chile's modern wine era began.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"], ["Main grapes", "Cabernet Sauvignon, Sauvignon Blanc, Merlot, Carmenère, Chardonnay, País"]], "sections": [["The place", "<p>In 1979 the Catalan producer Miguel Torres bought land here and brought stainless steel tanks and temperature-controlled fermentation, technologies that spread through the country in the following decade. The subregion covers Curicó province plus Río Claro commune and has two zones: Teno in the north and Lontué in the south.</p><p>It is a workhorse valley with more grape varieties than anywhere else in Chile, best known for reliable Cabernet Sauvignon and Sauvignon Blanc, and home to big producers such as San Pedro at Molina, whose vineyard is among the largest single blocks in South America. Its edges are where the action is now: the dry-farmed hills of Rauco and Sagrada Familia (part of the Secano Interior), and the coastal Licantén DO near the mouth of the Mataquito.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["History", "<p>In 1979 the Catalan producer Miguel Torres bought land at Curicó and brought stainless-steel tanks and temperature-controlled fermentation, a revolution in a country of old rauli-wood vats. Torres helped trigger the modernisation that made Chile an export power in the 1990s, and its Estelado País sparkling wine later helped revive interest in the old variety.</p>"], ["In the glass", "<p>Fresh Sauvignon Blanc, Cabernet and everyday blends.</p>"], ["For the exam", "<p>Miguel Torres 1979; stainless steel; Teno and Lontué zones.</p>"]], "producers": ["Miguel Torres", "San Pedro", "Echeverría", "Valdivieso", "Aresti"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-del-cachapoal"] = {"lede": "Cachapoal is the northern zone of Rapel, following the Cachapoal river from the Andes past Rancagua to Lake Rapel.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"], ["Main grapes", "Carmenère, Cabernet Sauvignon, Merlot, Syrah"]], "sections": [["The place", "<p>Its east, under the mountains (Requínoa, Machalí, Rengo), is Cabernet country, home to Altaïr and the Andes-side vineyards of Viña San Pedro. Its west, around Peumo, Pichidegua and Las Cabras, is the warm, sheltered bowl where Chilean Carmenère reaches its fullest, ripest form: Concha y Toro's Carmín de Peumo and Terrunyo Carmenère come from here.</p><p>Before 1994 Chileans called the late-ripening vine here 'Merlot Peumal' after the Peumo valley, and the name stuck as a nickname for Carmenère. The area also hides Vik in Millahue, a showpiece estate with a winery built over water. In the glass, Peumo Carmenère is plush and spicy with dark fruit, and Andes-side Cabernet is firmer and fresher.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["History", "<p>Cachapoal's best-known names include Altaïr, a joint project between Viña San Pedro and Château Dassault in the Andean foothills, and Peumo, where Concha y Toro sources Carmenère for Terrunyo and Carmín de Peumo.</p>"], ["In the glass", "<p>Ripe Carmenère (especially from Peumo), Cabernet and Bordeaux blends.</p>"], ["For the exam", "<p>Rapel zone; Peumo Carmenère; Altaïr (Requínoa).</p>"]], "producers": ["Concha y Toro (Peumo)", "Altaïr", "Vik", "Torreón de Paredes", "Misiones de Rengo", "Casas del Toqui"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-del-claro"] = {"lede": "Claro is the northern zone of Maule, named after the river through Talca: Talca, San Clemente, Pencahue, Maule, Pelarco, San Rafael, Empedrado and Curepto communes.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>It runs from Andean San Clemente to the coastal slate of Empedrado.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["In the glass", "<p>Varied.</p>"], ["For the exam", "<p>Valle del Claro: Valle Central level of the Chilean DO hierarchy.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-del-loncomilla"] = {"lede": "Loncomilla is the central zone of Maule, along the Loncomilla river: San Javier, Villa Alegre, Retiro, Parral, Linares, Yerbas Buenas, Colbún and Longaví communes.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>It mixes large irrigated estates with the old dry-farmed Carignan and País of the western hills around San Javier and Villa Alegre.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["In the glass", "<p>Varied.</p>"], ["For the exam", "<p>Valle del Loncomilla: Valle Central level of the Chilean DO hierarchy.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-del-lontue"] = {"lede": "Lontué is the southern zone of Curicó, along the Lontué river: Curicó, Molina and Sagrada Familia communes plus Río Claro in Talca province.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>It is the valley's productive centre, with large estates around Molina and Lontué.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["In the glass", "<p>Varied.</p>"], ["For the exam", "<p>Valle del Lontué: Valle Central level of the Chilean DO hierarchy.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-del-maipo"] = {"lede": "Maipo is the historic heart of Chilean fine wine and the home of its most famous Cabernet Sauvignon.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"], ["Vineyard area", "About 8,898 ha"], ["Main grapes", "Cabernet Sauvignon, Carmenère, Merlot, Syrah, Cabernet Franc; some Chardonnay and Sauvignon Blanc"]], "sections": [["The place", "<p>When Santiago's 19th-century mining and banking aristocracy came home from Paris, they planted Bordeaux varieties on their estates at the city's edge: Silvestre Ochagavía imported French vines and a French winemaker in 1851, Cousiño Macul was founded in 1856, Santa Carolina in 1875, Santa Rita in 1880 and Concha y Toro at Pirque in 1883. Those estates, a short carriage ride from the capital, defined the Chilean style for a century.</p><p>The subregion covers the whole Metropolitan Region, from the Andean foothills to the coastal range, and growers split it three ways. Alto Maipo, on the Andean piedmont at 600 to 800 m (Puente Alto, Pirque, Santiago's Macul and Peñalolén), has stony alluvial terraces of the Maipo river and cold mountain air at night; it gives Chile's classic Cabernet, with cassis, graphite and the hint of mint or eucalyptus locals call the Maipo signature. Central Maipo (Buin, Paine, Isla de Maipo, Talagante) is warmer and flatter, a source of generous Cabernet and Carmenère. Pacific Maipo, towards Melipilla and Alhué, feels the sea breeze and is the newest frontier.</p><p>The wines to know come mostly from a 10 km stretch of Puente Alto: Don Melchor (first vintage 1987), Almaviva (the 1997 Concha y Toro and Baron Philippe de Rothschild joint venture) and Viñedo Chadwick, whose 2000 vintage won the 2004 Berlin Tasting. Maipo Cabernet is firmer and more savoury than Napa's, more sun-filled than Bordeaux, and among the best-value long-agers in the world.</p><p>Stony alluvial terraces of the Maipo river (Puente Alto's 'piedmont' gravels), colluvial fans at the foot of the Andes, warmer clay-loams in the centre and granitic coastal hills in the west; Mediterranean climate, about 300 to 350 mm of winter rain, cold Andean night winds.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["History", "<p>Maipo was the playground of nineteenth-century Santiago's mining and banking fortunes, who built French-style estates with Bordeaux vines: Cousiño Macul (1856), Santa Rita (1880), Concha y Toro (1883) and Undurraga (1885). Its stony Andean terraces at Puente Alto and Pirque gave the Cabernets that put Chile on the fine-wine map: Concha y Toro's Don Melchor (first vintage 1987) and Almaviva, the joint venture with Baron Philippe de Rothschild launched with the 1996 vintage. Santiago's spread has swallowed many historic vineyards.</p>"], ["In the glass", "<p>Cabernet Sauvignon with cassis, mint and dusty tannin, the 'Maipo mint'; Carmenère and blends.</p>"], ["For the exam", "<p>Historic heart; Alto Maipo Cabernet; Don Melchor, Almaviva; Cousiño Macul, Santa Rita, Concha y Toro, Undurraga.</p>"]], "producers": ["Concha y Toro (Don Melchor)", "Almaviva", "Viñedo Chadwick", "Santa Rita", "Cousiño Macul", "Viña Carmen", "Antiyal", "De Martino", "Haras de Pirque", "Viña Aquitania", "Undurraga", "Santa Carolina"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-del-maule"] = {"lede": "Maule is Chile's biggest wine subregion by far.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"], ["Main grapes", "Cabernet Sauvignon, Sauvignon Blanc, Merlot, Carmenère, Chardonnay, País, Carignan, Cinsault, Malbec"]], "sections": [["The place", "<p>SAG's 2024 census put 48,565 ha of wine grapes in the Maule administrative region (which also contains Curicó), 41.5% of the national total, and in 2026 that administrative region made 452 million litres, about 48% of all Chilean wine. Much of that is bulk Cabernet, Sauvignon Blanc and Merlot from irrigated valley floor; but Maule also holds the country's deepest well of history. Spanish settlers planted País here in the 16th century, and on the dry-farmed granite hills of the coastal range, the *secano*, head-trained bush vines of País, Carignan and Cinsault, some well over a century old, survived every modernisation simply because nobody bothered to rip them out.</p><p>The decree splits Maule into three zones. Claro (around Talca) runs from Andean San Clemente to coastal Empedrado and Curepto, where slate soils give rare mineral reds. Loncomilla (Linares, San Javier, Parral, Villa Alegre, Colbún) is the warm central valley plus the old Carignan of the dry hills. Tutuvén is the single area of Cauquenes, the epicentre of dry-farmed País and Carignan.</p><p>Since about 2010 the VIGNO (Vignadores de Carignan) association has defined a Maule Carignan style from old, dry-farmed bush vines, and a new generation (Bouchon, Gillmore, González Bastías, Garage Wine Co, De Martino and many more) bottles País and Cinsault that taste of wild strawberry, earth and dust. Maule is where Chile reconnects with its first four centuries of wine.</p><p>Volcanic and alluvial soils on the irrigated valley floor; granite, decomposed granite (*maicillo*) and slate on the dry-farmed coastal hills; cooler and wetter than the Maipo, with about 700 mm of rain.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["History", "<p>Maule is the biggest wine subregion in Chile and the reservoir of its heritage: dry-farmed bush vines of País, Carignan and Cinsault, some more than a century old, on the granite hills of the coastal range. Carignan was widely planted after the 1939 Chillán earthquake to add colour and acidity to País. In 2010 a group of growers formed VIGNO (Vignadores de Carignan), Chile's first producer-defined appellation-style brand, requiring at least 65% Carignan from dry-farmed vines more than 30 years old in Maule's secano interior.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Largest subregion; secano interior; VIGNO 2010 (65% Carignan, 30+ year dry-farmed vines); País revival.</p>"]], "producers": ["Gillmore", "J. Bouchon", "Viña Gonzalez Bastías", "Garage Wine Co", "Odfjell", "Miguel Torres (Empedrado, Cordillera)", "Valdivieso", "Undurraga (VIGNO)", "Concha y Toro"], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-del-rapel"] = {"lede": "The Rapel subregion covers the O'Higgins administrative region, named after the Rapel river that forms where the Cachapoal and Tinguiririca join.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"], ["Vineyard area", "About 36,026 ha"], ["Main grapes", "Cabernet Sauvignon, Carmenère, Merlot, Syrah, Malbec, Sauvignon Blanc"]], "sections": [["The place", "<p>It contains two zones, Cachapoal to the north and Colchagua to the south, and SAG figures show O'Higgins making about 282 million litres of DO wine in 2026, second only to Maule. 'Valle del Rapel' alone on a label usually means a blend across both zones; serious bottles name Cachapoal, Colchagua or an area.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["In the glass", "<p>Varied.</p>"], ["For the exam", "<p>Valle del Rapel: Valle Central level of the Chilean DO hierarchy.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-del-teno"] = {"lede": "Teno is the northern zone of Curicó, along the Teno river and the Mataquito towards the coast: Teno, Romeral, Rauco, Hualañé and Vichuquén communes.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>It runs from Andean piedmont at Romeral through warm valley floor to coastal hills near Lake Vichuquén.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["In the glass", "<p>Varied.</p>"], ["For the exam", "<p>Valle del Teno: Valle Central level of the Chilean DO hierarchy.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-valle-del-tutuven"] = {"lede": "Tutuvén is Maule's southern-coastal zone, consisting only of Cauquenes commune, named after the Tutuvén river.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>It is the heart of Chile's dry-farmed old-vine country.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term.</p>"], ["In the glass", "<p>Varied.</p>"], ["For the exam", "<p>Valle del Tutuvén: Valle Central level of the Chilean DO hierarchy.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-vichuquen"] = {"lede": "Area matching Vichuquén commune on the coast around Lake Vichuquén, with new cool-climate plantings of Sauvignon Blanc and Pinot Noir.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Costa*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Vichuquén is classed as 'Costa', so its wines may add that term.</p>"], ["In the glass", "<p>Fresh Sauvignon Blanc, Cabernet and everyday blends.</p>"], ["For the exam", "<p>Area within Valle de Curicó (Valle Central region); 'Costa' area.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
APXF["cl-villa-alegre"] = {"lede": "Area matching Villa Alegre commune south of Talca, with vineyards on the Loncomilla plain and old secano vines nearby.", "facts": [["Category", "DO"], ["Recognized", "1994 (Decreto 464)"]], "sections": [["The place", "<p>Labels may add the complement *Entre Cordilleras*.</p>"], ["The rules", "<p>A denomination of origin. Chile's denominations of origin were created by Decreto 464 of December 1994, under the wine law (Ley 18.455), and are administered by the Servicio Agrícola y Ganadero (SAG). The system is a geographic zoning, not a rulebook: the country is divided into viticultural regions, subregions, zones and areas, mostly following provincial and communal boundaries. A wine with a DO must contain at least 75% wine from the named place, and the same 75% applies to a named variety and vintage; it must be bottled in Chile. There are no rules on yields, winemaking or style, except for the special Secano Interior denomination. Since 2012 labels may add the terms Andes, Entre Cordilleras or Costa when at least 85% of the wine comes from areas officially classed under that term. Villa Alegre is classed as 'Entre Cordilleras', so its wines may add that term. Its dry-farmed vineyards may also use the special Secano Interior denomination for País and Cinsault.</p>"], ["In the glass", "<p>Old-vine, dry-farmed Carignan, País and Cinsault; Cabernet and Carmenère from irrigated plains.</p>"], ["For the exam", "<p>Area within Valle del Maule (Valle Central region); 'Entre Cordilleras' area; Secano Interior eligible.</p>"]], "producers": [], "sources": [["Decreto 464 (1994): Zonificación vitícola, Ley Chile, Biblioteca del Congreso Nacional", "https://www.bcn.cl/leychile/navegar?idNorma=13601"], ["SAG: Decreto 464 consolidated text", "https://www.sag.gob.cl/sites/default/files/decreto_ndeg_464.pdf"]], "checked": "2026-11-14"};
})();
